nodes=0
@lru_cache(None)
def search(occ, counts):
 global nodes
 nodes+=1
 if occ==Tbits:
  return () if not any(counts) else None
 free=Tbits & ~occ
 bestcand=None
 b=free
 while b:
  low=b&-b; pos=low.bit_length()-1; b-=low
  cand=[]
  for ti,oi,bits,dr,dc in cellopts[pos]:
   if counts[ti] and not (bits&occ): cand.append((ti,oi,bits,dr,dc))
